INSERT INTO "Service" ("id","slug","title","summary","description","icon","features","order","published","createdAt","updatedAt") VALUES ('3cf9eb01-ed73-4094-809a-5dd4e987142f','soy-bagi-ile-vatandaslik','Soy Bağı ile Vatandaşlık','Soy bağınızı kanıtlayarak vatandaşlık kazanma sürecinde uçtan uca rehberlik.','Atalarınızdan gelen soy bağınız yeni bir vatandaşlık için kapı açabilir. Hangi belgelerin gerektiğini, sürecin nasıl işlediğini ve uygunluk şartlarını sizin için baştan sona yönetiyoruz.'||char(10)||''||char(10)||'## Süreç nasıl işliyor?'||char(10)||''||char(10)||'Önce soy bağınızı ve uygunluğunuzu değerlendiriyoruz. Ardından gereken nüfus ve arşiv kayıtlarını araştırıp belgeleri eksiksiz topluyor, tercüme ve resmi işlemleri tamamlayıp başvuruyu yapıyoruz.'||char(10)||''||char(10)||'## Hizmet kapsamı'||char(10)||''||char(10)||'- Soy bağı ve uygunluk analizi'||char(10)||''||char(10)||'- Nüfus kayıtları ve arşiv araştırması'||char(10)||''||char(10)||'- Belge toplama, tercüme ve noter işlemleri'||char(10)||''||char(10)||'- Başvuru hazırlığı ve sonuca kadar takip'||char(10)||''||char(10)||'Durumunuzu değerlendirmek için ücretsiz ön görüşme talep edebilirsiniz.','Scale','Soy bağı ve uygunluk değerlendirmesi'||char(10)||'Nüfus ve arşiv kayıtlarının araştırılması'||char(10)||'Belge toplama, tercüme ve noter işlemleri'||char(10)||'Başvuru dosyasının hazırlanması'||char(10)||'Başvuru takibi ve süreç yönetimi',5,1,1791933778306,1791933778306);
